 <div className="wall-header-tools"><Tool label="导入照片，可批量选择" onClick={()=>chooseImages()} disabled={!!busy}><Upload size={16}/><span>照片</span></Tool><Tool label="添加便签" onClick={addNote} disabled={!!busy}><StickyNote size={16}/><span>便签</span></Tool><span className="wall-tool-divider"/><Tool label="撤销，Ctrl / ⌘ Z" onClick={undo} disabled={!history.current.undo.length||!!busy||dragging}><Undo2 size={17}/></Tool><Tool label="重做，Ctrl / ⌘ Shift Z" onClick={redo} disabled={!history.current.redo.length||!!busy||dragging}><Redo2 size={17}/></Tool><span className="wall-tool-divider"/><Tool label="选择并拖动照片" active={tool==='move'} onClick={()=>{setTool('move');setConnectFrom(null)}}><MousePointer2 size={17}/></Tool><Tool label="抓手，拖动浏览画布" active={tool==='pan'} onClick={()=>{setTool('pan');setConnectFrom(null)}}><Hand size={17}/></Tool><Tool label="连接照片：依次点击两张照片；也可选中已有红线" active={tool==='connect'} onClick={()=>{setTool(v=>v==='connect'?'move':'connect');setConnectFrom(null)}}><Link2 size={17}/><span>连线</span></Tool><span className="wall-tool-divider"/><Tool label="缩小画布" onClick={()=>setZoom(z=>clamp(z-.25,.5,3))}><ZoomOut size={16}/></Tool><button className="wall-zoom-value" title="适合窗口" onClick={()=>setZoom(1)}>{Math.round(zoom*100)}%</button><Tool label="放大画布" onClick={()=>setZoom(z=>clamp(z+.25,.5,3))}><ZoomIn size={16}/></Tool><span className="wall-toolbar-spacer"/><Tool label="照片属性与图层" active={panelOpen} onClick={()=>setPanelOpen(v=>!v)}><Settings2 size={17}/></Tool><Tool label="操作帮助" active={help} onClick={()=>setHelp(v=>!v)}><HelpCircle size={17}/></Tool><Tool label="导出、导入与重置" active={more} onClick={()=>setMore(v=>!v)}><MoreHorizontal size={20}/></Tool></div>
